import{_ as t,o,c as r,ag as n}from"./chunks/framework.Cyu1VozZ.js";const g=JSON.parse('{"title":"Version History","description":"","frontmatter":{},"headers":[],"relativePath":"guide/version-history.md","filePath":"guide/version-history.md"}'),a={name:"guide/version-history.md"};function s(i,e,h,d,l,c){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h1><p>Wafflebase keeps a history of every sheet, document, presentation, note, and board as you work. You can look back at an earlier version, open it read-only, and roll the document back to it — and rolling back is itself reversible.</p><p>History is kept for the five editable document types. PDFs, images, and other uploaded files are stored as they were uploaded and have no version history.</p><h2 id="open-the-panel" tabindex="-1">Open the panel <a class="header-anchor" href="#open-the-panel" aria-label="Permalink to &quot;Open the panel&quot;">​</a></h2><p>Click the <strong>history</strong> icon in the editor header. It is a toggle, not a menu item: clicking it again closes the panel, which docks on the right side of the editor.</p><p>The panel is available when you are signed in and opening the document from your workspace. It is not part of a share link — someone reading or editing through a shared URL has no history panel and no way to restore.</p><div class="warning custom-block"><p class="custom-block-title">Presentations need a wide window</p><p>Under 768 pixels wide — so most phones — a presentation opens in a mobile layout that has no history icon and no panel. The history is still being kept; you just cannot reach it until you open the deck on a wider screen. Sheets, documents, notes, and boards keep the icon at every width.</p></div><h2 id="what-the-list-shows" tabindex="-1">What the list shows <a class="header-anchor" href="#what-the-list-shows" aria-label="Permalink to &quot;What the list shows&quot;">​</a></h2><p>Versions are grouped under a heading per day — the weekday and full date, written the way your browser&#39;s language settings write dates — newest first, with the time beside each entry.</p><p>Most entries are named <strong>Automatic</strong>. Wafflebase does not decide when those are taken — the server records one each time it snapshots the document, so the timeline follows editing activity rather than the clock. A quiet week produces no entries; an afternoon of heavy editing produces several.</p><p>The entries that are not automatic are the ones a person created: versions you named, and the <strong>Before restore</strong> versions that a restore creates. Those carry their author, and <strong>By you</strong> appears under any of them that you created yourself. An automatic version has no author to show.</p><p>If the document is new enough to have no versions yet, the panel says <strong>No versions yet</strong> rather than showing an empty list.</p><h2 id="name-the-current-version" tabindex="-1">Name the current version <a class="header-anchor" href="#name-the-current-version" aria-label="Permalink to &quot;Name the current version&quot;">​</a></h2><p>To mark a moment you will want to find again, type a label into <strong>Name current version</strong> at the top of the panel and click <strong>Save</strong>. The new entry appears in the list immediately.</p><p>Naming applies to the document <strong>as it is right now</strong>. There is no way to rename a version after the fact — an entry in the list offers <strong>Preview</strong> and <strong>Restore</strong> and nothing else — so name the state you are in before you move on from it.</p><h2 id="preview-a-version" tabindex="-1">Preview a version <a class="header-anchor" href="#preview-a-version" aria-label="Permalink to &quot;Preview a version&quot;">​</a></h2><p><strong>Preview</strong> opens that version read-only over your editor, with a banner reading <em>Viewing … from …</em>. Nothing is changed by looking.</p><p>While a preview is open the editing toolbar is removed rather than dimmed, and keyboard shortcuts do not reach the live document — so an absent-minded <strong>⌘+Z</strong> / <strong>Ctrl+Z</strong> cannot undo real work behind the preview. The history panel stays beside it and stays clickable: select another entry to page straight to it. Click <strong>Back to current version</strong> to leave.</p><p>What a preview shows depends on the document type:</p><table tabindex="0"><thead><tr><th>Type</th><th>In a preview</th></tr></thead><tbody><tr><td><strong>Sheet</strong></td><td>The first tab only. The tab bar is covered, so you cannot switch tabs inside a preview, and a note above the grid says that charts and images are not drawn.</td></tr><tr><td><strong>Document</strong></td><td>The paginated document, read-only. The comments panel closes while the preview is open and reopens when you leave.</td></tr><tr><td><strong>Presentation</strong></td><td>One slide at a time — use the <strong>‹ / ›</strong> control in the banner to move through the deck.</td></tr><tr><td><strong>Note</strong></td><td>The rendered markdown, without the source pane.</td></tr><tr><td><strong>Board</strong></td><td>The whole board, framed to fit its content. There is no panning or zooming inside a board preview.</td></tr></tbody></table><p>A sheet whose tabs are all external (a datasource or lakehouse connection) has nothing to draw, and says so: those rows live in the connected database, not in the document.</p><h2 id="restore-a-version" tabindex="-1">Restore a version <a class="header-anchor" href="#restore-a-version" aria-label="Permalink to &quot;Restore a version&quot;">​</a></h2><p><strong>Restore</strong> rolls the document back. Before it does anything else, Wafflebase saves the state you are leaving as a version called <strong>Before restore</strong>, so a restore is always reversible — if the version you picked was the wrong one, restore <strong>Before restore</strong>. If that safety version cannot be saved, the restore does not run at all.</p><p>A restore replaces the whole document, not just the part a preview happened to show: every tab of a sheet, every slide of a deck. Your undo history is discarded at the same time, because it describes a document that no longer exists — <strong>⌘+Z</strong> / <strong>Ctrl+Z</strong> will not walk a restore back, and <strong>Before restore</strong> is what you use instead.</p><div class="warning custom-block"><p class="custom-block-title">Comments come back with the version</p><p><a href="/docs/guide/collaboration.html#comments-mentions">Comments</a> live inside the document, so they are part of the version being restored. Any comment added after that version was created is removed along with the rest of the newer content. The confirmation dialog says so before you commit.</p></div><div class="warning custom-block"><p class="custom-block-title">Only one of the two Restore buttons asks you to confirm</p><p><strong>Restore</strong> in the version list opens a confirmation dialog first, so you can back out. <strong>Restore this version</strong> inside an open preview does <strong>not</strong> — it restores immediately, on the reasoning that the preview you are looking at is itself the confirmation. If you previewed a version to check it and then decide against restoring it, leave with <strong>Back to current version</strong> rather than expecting a dialog to catch you.</p></div><p>Only one restore runs at a time. If a collaborator&#39;s restore — or your own, started from a preview — is already in flight, the buttons are disabled and a second attempt is refused with <em>A restore is already in progress</em> rather than queued. Everything that fails says so in the panel; a restore never fails quietly.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>The panel shows the 50 most recent versions.</strong> There is no paging and no &quot;load older&quot;: on a long-lived document, versions past the 50th are not reachable from the panel at all.</li><li><strong>Versions cannot be deleted or renamed</strong> from the panel.</li><li><strong>Signed-in only.</strong> History is absent from share links entirely, for viewers and editors alike.</li><li><strong>No history for PDFs, images, or other uploaded files.</strong></li><li><strong>Presentations have no history panel below 768 pixels wide.</strong></li></ul>',29)])])}const u=t(a,[["render",s]]);export{g as __pageData,u as default};
